#include <print>
#include <string>
#include <utility>

class Locker {
public:
    explicit Locker(std::string who) : who_(std::move(who)) {
        std::println("{}：投币，柜门开了（构造=借资源）", who_);
    }
    ~Locker() {
        std::println("{}：拔钥匙，柜门锁了（析构=还资源）", who_);
    }
    Locker(const Locker&) = delete;
private:
    std::string who_;
};

int main() {
    Locker x("外层");
    {
        Locker y("内层");
        Locker z("内层二号");
        std::println("  ……内层干活……");
    }
    std::println("  ……外层还在……");
    return 0;
}
// 格子合上时 z 先还、y 后还，外层的 x 等 main 结束才走：后借的先还

